#!/usr/bin/env bash
# Self-extracting application package; generated by scripts/package_k3.py.
set -euo pipefail
command -v python3 >/dev/null || { echo '需要 Python 3.11+' >&2; exit 1; }
tmp="$(mktemp -d)"
trap 'rm -rf -- "$tmp"' EXIT
python3 - "$0" "$tmp" '@OFFSET@' '@SHA256@' <<'PY'
import hashlib, io, pathlib, sys, tarfile
source, target, offset, expected = sys.argv[1:]
with open(source, 'rb') as stream:
    stream.seek(int(offset))
    data = stream.read()
if hashlib.sha256(data).hexdigest() != expected:
    raise SystemExit('安装包校验失败，拒绝安装。请重新下载。')
with tarfile.open(fileobj=io.BytesIO(data), mode='r:gz') as archive:
    members = archive.getmembers()
    if sum(m.size for m in members) > 1024**3:
        raise SystemExit('解压大小超出限制。')
    for member in members:
        path = pathlib.PurePosixPath(member.name)
        if path.is_absolute() or '..' in path.parts or not (member.isfile() or member.isdir()):
            raise SystemExit('安装包包含不安全路径或链接。')
    # Every member has been checked; links/devices are forbidden even on Python 3.11.
    archive.extractall(target, members=members)
PY
bash "$tmp/k3-meeting-assistant/install.sh" "$@"
exit $?
# BINARY PAYLOAD FOLLOWS
